const products=collections.flatMap((c,category)=>c.products.map(p=>({id:p[0],name:p[1],variant:p[2],price:p[3],image:p[4],description:p[5],category,collection:c.name})));
const find=id=>products.find(p=>p.id===id);
let favorites=new Set();try{favorites=new Set(JSON.parse(localStorage.getItem('hemkora-catalog-favorites')||'[]').filter(id=>find(id)))}catch{}
let index=0,turning=false,toastTimer,lastFocus=null;
const book=document.getElementById('book'),left=document.getElementById('left-page'),right=document.getElementById('right-page');
const drawer=document.getElementById('favorites-drawer'),backdrop=document.getElementById('drawer-backdrop');
const productDialog=document.getElementById('product-dialog'),howDialog=document.getElementById('how-dialog');
const mobile=()=>matchMedia('(max-width:760px)').matches;
const reduced=()=>matchMedia('(prefers-reduced-motion:reduce)').matches;
const number=n=>String(n).padStart(2,'0');
function heart(p){return `<button class="heart-button" data-favorite="${p.id}" aria-label="${favorites.has(p.id)?'Quitar de':'Añadir a'} favoritos: ${p.name}" aria-pressed="${favorites.has(p.id)}">${icon('heart')}</button>`}
function card(p){return `<article class="product-card"><button class="product-image-button" data-product="${p.id}" aria-label="Ver ${p.name}"><img src="${asset(p.image)}" alt="${p.name}, imagen de referencia" loading="lazy" width="400" height="400"></button>${heart(p)}<button class="product-name" data-product="${p.id}">${p.name}</button><span class="product-variant">${p.variant}</span><strong class="product-price">${price(p.price)}</strong></article>`}
function editorial(i){const c=collections[i];return `<div class="editorial-page"><img class="editorial-image" src="${asset(c.image)}" alt="Inspiración de la colección ${c.name}" width="600" height="800"><div class="editorial-top"><span>HEMKORA — THE EDIT</span><span class="editorial-number">${number(i+1)}</span></div><div class="editorial-copy"><span>${c.name.toUpperCase()}</span><h3>${c.title}</h3><p>${c.copy}</p></div><div class="paper-footer"><span>HECHO PARA INSPIRARTE</span><span>${number(i*2+1)}</span></div></div>`}
function productPage(i){const c=collections[i];return `<div class="products-page"><div class="products-heading"><h3>${c.name}</h3><span>THE HEMKORA EDIT</span></div><div class="product-grid">${products.filter(p=>p.category===i).map(card).join('')}</div><div class="products-footer"><span>ENCUENTRA LO QUE TE HACE BRILLAR</span><span>${number(i*2+2)}</span></div></div>`}
function controls(){document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.category)===index));document.getElementById('previous').disabled=index===0||turning;document.getElementById('next').disabled=index===collections.length-1||turning;document.getElementById('page-counter').innerHTML=`${number(index+1)} <span>/ ${number(collections.length)}</span>`;document.getElementById('book-progress').style.width=`${(index+1)/collections.length*100}%`;book.setAttribute('aria-label',`Catálogo de ${collections[index].name}, colección ${index+1} de 6. Usa las flechas para pasar de página.`)}
function render(){left.innerHTML=editorial(index);right.innerHTML=productPage(index);controls()}
function turn(next){
 if(turning||next===index||next<0||next>=collections.length)return;
 if(reduced()){index=next;render();return}
 turning=true;controls();const forward=next>index,isMobile=mobile();
 const leaf=document.createElement('div');leaf.className=`flip-leaf ${forward?'forward':'backward'}`;leaf.setAttribute('aria-hidden','true');leaf.inert=true;
 leaf.innerHTML=`<div class="leaf-face leaf-front">${isMobile?productPage(index):forward?productPage(index):editorial(index)}</div><div class="leaf-face leaf-back">${isMobile?productPage(next):forward?editorial(next):productPage(next)}</div>`;
 if(forward){right.innerHTML=productPage(next)}else{left.innerHTML=editorial(next);if(isMobile)right.innerHTML=productPage(next)}
 book.append(leaf);
 let done=false;const finish=()=>{if(done)return;done=true;leaf.remove();index=next;turning=false;render()};
 leaf.addEventListener('animationend',e=>{if(e.target===leaf)finish()});setTimeout(finish,1100);
}
document.getElementById('category-tabs').innerHTML=collections.map((c,i)=>`<button data-category="${i}" aria-pressed="${i===0}">${c.name}</button>`).join('');
document.getElementById('category-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(b)turn(Number(b.dataset.category))});
document.getElementById('previous').addEventListener('click',()=>turn(index-1));document.getElementById('next').addEventListener('click',()=>turn(index+1));
book.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();turn(index+1)}if(e.key==='ArrowLeft'){e.preventDefault();turn(index-1)}});
let touchStart=null;book.addEventListener('touchstart',e=>{if(e.touches.length===1)touchStart={x:e.touches[0].clientX,y:e.touches[0].clientY}},{passive:true});book.addEventListener('touchend',e=>{if(!touchStart)return;const dx=e.changedTouches[0].clientX-touchStart.x,dy=e.changedTouches[0].clientY-touchStart.y;touchStart=null;if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)*1.5)turn(index+(dx<0?1:-1))},{passive:true});
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000)}
function persist(){try{localStorage.setItem('hemkora-catalog-favorites',JSON.stringify([...favorites]))}catch{}document.querySelectorAll('[data-count]').forEach(el=>el.textContent=favorites.size);document.querySelectorAll('[data-favorite]').forEach(b=>{const p=find(b.dataset.favorite);b.setAttribute('aria-pressed',favorites.has(p.id));b.setAttribute('aria-label',`${favorites.has(p.id)?'Quitar de':'Añadir a'} favoritos: ${p.name}`)});renderFavorites()}
function toggleFavorite(id){if(!find(id))return;const removed=favorites.delete(id);if(!removed)favorites.add(id);persist();toast(removed?'Quitado de tus favoritos':'Guardado en tus favoritos');const detailButton=productDialog.querySelector('[data-detail-favorite]');if(detailButton&&detailButton.dataset.detailFavorite===id)updateDetailButton(id)}
function renderFavorites(){const selected=[...favorites].map(find);document.getElementById('favorites-list').innerHTML=selected.length?selected.map(p=>`<div class="favorite-row"><img src="${asset(p.image)}" alt="${p.name}" width="76" height="94"><div><h3>${p.name}</h3><small>${p.collection}</small><strong>${price(p.price)}</strong></div><button data-remove="${p.id}" aria-label="Quitar ${p.name}">${icon('close')}</button></div>`).join(''):`<div class="empty-favorites">${icon('heart')}Todavía no has guardado favoritos.<br>Busca un corazón en el catálogo<br>y empieza tu selección.</div>`;document.getElementById('selection-total').textContent=price(selected.reduce((n,p)=>n+p.price,0));document.getElementById('copy-selection').disabled=!selected.length}
function openFavorites(){lastFocus=document.activeElement;renderFavorites();drawer.hidden=false;backdrop.hidden=false;document.querySelectorAll('main,.site-header,footer').forEach(el=>el.inert=true);document.body.style.overflow='hidden';document.querySelector('[data-close-favorites]').focus()}
function closeFavorites(){drawer.hidden=true;backdrop.hidden=true;document.querySelectorAll('main,.site-header,footer').forEach(el=>el.inert=false);document.body.style.overflow='';lastFocus?.focus()}
document.querySelectorAll('[data-open-favorites]').forEach(b=>b.addEventListener('click',openFavorites));document.querySelector('[data-close-favorites]').addEventListener('click',closeFavorites);backdrop.addEventListener('click',closeFavorites);
drawer.addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(b){const focusIndex=[...drawer.querySelectorAll('[data-remove]')].indexOf(b);toggleFavorite(b.dataset.remove);const remaining=drawer.querySelectorAll('[data-remove]');(remaining[Math.min(focusIndex,remaining.length-1)]||document.querySelector('[data-close-favorites]')).focus()}});
drawer.addEventListener('keydown',e=>{if(e.key==='Escape')closeFavorites();if(e.key==='Tab'){const focusables=[...drawer.querySelectorAll('button:not(:disabled)')];if(e.shiftKey&&document.activeElement===focusables[0]){e.preventDefault();focusables.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===focusables.at(-1)){e.preventDefault();focusables[0].focus()}}});
document.getElementById('copy-selection').addEventListener('click',async()=>{const selected=[...favorites].map(find);const text='Mi selección Hemkora\n\n'+selected.map(p=>`• ${p.name} — ${price(p.price)}`).join('\n')+'\n\nTotal de referencia: '+price(selected.reduce((n,p)=>n+p.price,0))+'\nCatálogo de muestra. Consultar disponibilidad y precios finales.';try{await navigator.clipboard.writeText(text);toast('Selección copiada. ¡Lista para compartir!')}catch{const area=document.createElement('textarea');area.value=text;area.style.cssText='position:fixed;top:10px;left:10px;width:1px;height:1px';drawer.append(area);area.select();try{const ok=document.execCommand('copy');toast(ok?'Selección copiada':'No se pudo copiar. Revisa el permiso del navegador.')}catch{toast('No se pudo copiar. Revisa el permiso del navegador.')}area.remove()}});
function updateDetailButton(id){const b=productDialog.querySelector('[data-detail-favorite]');if(b)b.innerHTML=`${icon('heart')} ${favorites.has(id)?'Guardado en favoritos':'Guardar en favoritos'}`}
function openProduct(id){const p=find(id);if(!p)return;document.getElementById('product-detail').innerHTML=`<div class="product-detail"><img class="detail-photo" src="${asset(p.image)}" alt="${p.name}, fotografía de referencia" width="600" height="800"><div class="detail-info"><span class="section-kicker">HEMKORA / ${p.collection.toUpperCase()}</span><h2>${p.name}</h2><p class="variant">${p.variant}</p><p class="price">${price(p.price)}</p><p class="description">${p.description}</p><button class="button button-dark" data-detail-favorite="${id}"></button><p class="sample-note">Producto, fotografía y precio ilustrativos.<br>Consulta la colección real y su disponibilidad con Hemkora.</p></div></div>`;updateDetailButton(id);productDialog.showModal()}
document.addEventListener('click',e=>{const favorite=e.target.closest('[data-favorite]');if(favorite){toggleFavorite(favorite.dataset.favorite);return}const detail=e.target.closest('[data-detail-favorite]');if(detail){toggleFavorite(detail.dataset.detailFavorite);return}const p=e.target.closest('[data-product]');if(p)openProduct(p.dataset.product)});
document.querySelector('[data-close-product]').addEventListener('click',()=>productDialog.close());
document.querySelectorAll('[data-how]').forEach(b=>b.addEventListener('click',()=>howDialog.showModal()));document.querySelectorAll('[data-close-how]').forEach(b=>b.addEventListener('click',()=>howDialog.close()));
for(const dialog of [productDialog,howDialog])dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
const curated=[['p1','Tu esencia','Una fragancia que se siente tuya.'],['c1','Tu compañía','El detalle que va contigo.'],['f1','Tu forma de querer','Regala un poquito de magia.']];
document.getElementById('curated-grid').innerHTML=curated.map(([id,title,copy])=>{const p=find(id);return `<button class="curated-card reveal" data-product="${id}" aria-label="${title}: ver ${p.name}"><div class="curated-image"><img src="${asset(p.image)}" alt="${p.name}" loading="lazy" width="600" height="800"></div><div><div><h3>${title}</h3><small>${copy}</small></div>${icon('arrow-up-right')}</div></button>`}).join('');
document.getElementById('year').textContent=new Date().getFullYear();render();persist();
if(!reduced()&&'IntersectionObserver'in window){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}})},{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}
// Warm the next spread to keep page turns smooth even on slower connections.
for(const name of new Set([...collections.map(c=>c.image),...products.map(p=>p.image)])){const img=new Image();img.src=asset(name)}
